  -- ---------------------------------------------------------------
  -- Capítulo 11 — Aprendizado ministerial  (aula ordem = 11)
  -- ---------------------------------------------------------------
  select id into v_aula_id from public.aulas
  where curso_id = v_curso_id and ordem = 11;

  if v_aula_id is null then
    insert into public.aulas (curso_id, titulo, ordem, conteudo)
    values (
      v_curso_id,
      $t$Capítulo 11 — Aprendizado ministerial$t$,
      11,
$conteudo$O que acontece entre alguém mostrar o potencial para ser separado para desenvolver responsabilidades específicas na obra do evangelho e chegar realmente a esse ponto (por exemplo, como um missionário, um evangelista ou um pastor numa igreja local)? A resposta normal é “seminário” ou “faculdade teológica”. Todavia, um número crescente de igrejas e candidatos ao ministério está fazendo uso de um passo intermediário – um treinamento ou aprendizado ministerial, que vem antes da educação teológica formal, que testa, treina e desenvolve pessoas ao longo do caminho para o ministério de tempo integral. Uma organização muito importante para ambos os autores – a Ministry Training Strategy (Estratégia de Treinamento Ministerial) – tem gasto mais de 20 anos ajudando igrejas a estabelecerem cursos de aprendizado ministerial na Austrália, com ramificações no Canadá, Inglaterra, França, República da Irlanda, Irlanda do Norte, Singapura, Nova Zelândia, Taiwan, Japão, Chile e África do Sul. A ideia básica é que “pessoas que vale a pena observarmos” são recrutadas para uma experiência de imersão total, por dois anos, de trabalho para uma igreja ou outro ministério cristão. Suas convicções, caráter e competências são testados e desenvolvidos. Sob a supervisão de um ministro experiente, tais pessoas “pegam” a natureza e o ritmo do ministério cristão, assimilando lições e habilidades valiosas e avaliando a sua adequabilidade para a obra do evangelho de longo prazo. O aprendizado da Ministry Training Strategy iniciou-se em 1979, quando Phillip Jensen começou a treinar alguns universitários talentosos e capazes que amavam a Deus. Naquele tempo, não havia a visão de longo prazo ou plano de expansão. Mas, desde 1979, mais de 1.200 aprendizes da Ministry Training Strategy foram treinados em igrejas e ministérios de campus em toda a Austrália. Destes aprendizes, mais de 200 estão presentemente engajados em estudo teológico em várias faculdades, e outros 400 homens e mulheres completaram seus estudos formais e estão agora servindo como obreiros de tempo integral ao redor do mundo. Uma das perguntas mais frequentes que nos tem sido feita no decorrer dos anos é: por que devemos nos importar com um aprendizado? Visto que enviamos nossos aprendizes para o estudo teológico formal, o aprendizado acrescenta realmente algo significativo? É um grande sacrifício para os candidatos ao ministério passarem dois anos extras em treinamento. Também é difícil pastores e igrejas proverem supervisão e remuneração para aprendizes que são frequentemente inexperientes e não testados. Que benefícios temos visto para aqueles que fazem um aprendizado ministerial? Eis algumas reflexões.

1. Os aprendizes aprendem a integrar a Palavra, a vida e a prática ministerial Na sala de aula, compartilhar e processar informações são o foco, e nem sempre é imediatamente óbvia a forma como a Palavra transforma a vida de um ministro. Há um nível de abstração inevitável e um tanto apropriado. Contudo, num aprendizado ministerial, o treinador e o aprendiz estudam as Escrituras juntos, semana após semana, e se esforçam por sua aplicação a questões pastorais, padrões teológicos e planos de ministério. O aprendiz aprende a pensar bíblica e teologicamente sobre tudo e desenvolve isso de maneira prática com seu treinador.

2. Os aprendizes são testados em seu caráter Um pastor que trabalha bem de perto com um aprendiz pode ver o que não pode ser visto no contexto de sala de aula. A lacuna entre a imagem e a realidade é exposta nas pressões e dificuldades da vida ministerial. A pessoa real é revelada – as verdadeiras motivações, a capacidade de amar e perdoar, as cicatrizes e feridas do passado e assim por diante. Um treinador sábio pode edificar o caráter piedoso do jovem ministro por meio da Palavra, da oração, da prestação de contas e de ser um modelo para ele.

3. Os aprendizes aprendem que o ministério diz respeito a pessoas e não a programas Sabemos que o ministério diz respeito à transformação de pessoas e à edificação de comunidades piedosas por meio do evangelho. Mais do que qualquer outra coisa, um aprendizado são dois anos de trabalho com pessoas – reunindo-se com crentes, discipulando novos cristãos, treinando líderes de ovens, liderando pequenos grupos ou confortando aqueles que passam por lutas. Nosso alvo é que os aprendizes passem 20 horas de sua semana em ministério com pessoas, face a face e com a Bíblia aberta. Eles aprendem, em primeira mão, que o ministério diz respeito a pessoas e não a estruturas.

4. Os aprendizes são bem preparados para o estudo teológico formal Durante os dois anos de envolvimento ministerial, muitas questões bíblicas e teológicas são levantadas e discutidas no contexto apropriado de evangelização e edificação da igreja. No final, os aprendizes estão ansiosos pela oportunidade de examinar rigorosamente estas questões num estudo posterior. A vida e a preparação para o ministério, e não o passar nas provas de admissão, se tornam a motivação e o contexto para estudo posterior. 5. Os aprendizes aprendem o ministério no mundo real Um dos problemas de sala de aula é que o aluno não precisa admitir as ideias da mesma maneira que precisa admiti-las no púlpito ou num ministério pastoral pessoa a pessoa. Seu aprendizado é abstraído da vida e ministério diários. Ele aprende sobre dez opiniões diferentes quanto à expiação, a fim de passar nas provas e não porque alguma coisa mostra a diferença entre elas. Ensinar a verdade aos outros ajuda o aprendiz a entender a importância do treinamento teológico. Outro problema de um modelo de treinamento puramente acadêmico é que ele se adapta a certas personalidades (ou seja, aos que são dispostos a ler, pensar, analisar e escrever). No entanto, alguns de nossos melhores evangelistas e plantadores de igreja podem ser pessoas que têm dificuldades em sala de aula. Estas pessoas florescem num contexto em que elas estão falando, pregando e edificando ministérios enquanto são instruídas ao longo do caminho. Na academia, elas seriam consideradas fracassos.

6. Os aprendizes aprendem como serem treinadores de outros, para que o ministério se multiplique Visto que os aprendizes recebem a experiência de instrução e acompanhamento pessoal quanto à vida e ao ministério, eles absorvem o que chamamos de “mentalidade de treinamento”. Quando estiverem liderando um ministério no futuro, equiparão instintivamente cooperadores e construirão equipes de ministério. Aqueles que aprendem o ministério apenas na sala de aula não captam a visão de confiar o ministério a outros. Aqueles que são treinados como aprendizes tendem a vislumbrar seus próprios aprendizes quando estiverem liderando uma igreja.

7. Os aprendizes aprendem evangelização e ministério empreendedor Os aprendizes são uma oportunidade para pensarmos estratégica e criativamente sobre o ministério. Em nosso contexto missionário pós-cristão, pluralista e multicultural, muitos pastores não têm mais um rebanho sentado nos bancos esperando o sermão de domingo. Os aprendizes podem experimentar novas maneiras de alcançar as pessoas e tomar a iniciativa para começarem novos grupos e novos programas.

De muitas maneiras, a Ministry Training Strategy (Estratégia de Treinamento Ministerial) é uma aplicação das palavras de Paulo dirigidas a Timóteo: “E o que de minha parte ouviste através de muitas testemunhas, isso mesmo transmite a homens fiéis e também idôneos para instruir a outros” (2 Tm 2.2). Quando Paulo chegou perto do final de sua vida, sabia que a proclamação fiel e contínua do evangelho não seria garantida pela redação de confissões doutrinárias ou pela criação de estruturas institucionais (por mais importantes que sejam). O evangelho só seria guardado e propagado se fosse passado de mãos fiéis para outras, à medida que cada geração de pregadores fiéis passasse o depósito sagrado à geração seguinte, que, por sua vez, ensinaria e treinaria outros. A Ministry Training Strategy se focaliza, realmente, em passar o bastão do evangelho à próxima geração de corredores. O manual da MTS sobre aprendizado ministerial – chamado Passando o Bastão – tem muitas informações sobre o que o aprendizado de dois anos pode conseguir, como estabelecê-lo e realizá-lo, como recrutar aprendizes e assim por diante. Não repetiremos as informações aqui. No entanto, vale a pena refletirmos um pouco mais sobre onde chegamos no ciclo de treinamento e crescimento. Começamos, você lembra, por dizer que todos os cristãos deveriam ser treinados para serem discípulos que fazem discípulos – treinados em seu conhecimento de Deus (convicções), sua piedade (caráter) e sua habilidade para servir a outros (competências). Sugerimos que a maneira de iniciarmos era escolher apenas um pequeno grupo de potenciais cooperadores e começar a treiná-los, na expectativa de que alguns destes cooperadores seriam, por sua vez, capazes de treinar outros. À medida que este ciclo de treinamento continua, uma força-tarefa de fazedores de discípulos começa a se formar – pessoas que trabalham ao seu lado para ajudar outras a fazerem progresso no “crescimento evangélico”. À medida que você continua discipulando e treinando, começa a notar certas pessoas que têm potencial para o ministério – pessoas que vale a pena observarmos. São pessoas que você desafia e recruta como a próxima geração de “trabalhadores do evangelho reconhecidos”. Elas fazem um aprendizado ministerial e, depois, vão para a faculdade bíblica ou teológica; após, elas seguem para o ministério e começam a treinar outros... e o ciclo começa novamente.

É assim, pelo menos, que a teoria deve funcionar. Mas é claro que, na realidade, ela tende a ser confusa e não tão fácil de ser traçada. Alguns aprendizes de ministério não vão para a faculdade teológica – o seu treinamento de dois anos os ajuda a perceber (ou ajuda seus treinadores a perceberem) que eles não têm o caráter ou as competências reconhecidas para a obra do evangelho. Para aqueles que vão à faculdade teológica, uma enorme variedade de ministérios os espera do outro lado – desde o tornarem-se missionários no exterior a pastorearem uma congregação, a retornarem ao trabalho secular e a serem cooperadores voluntários em uma nova plantação de igreja. As coisas também ficam confusas porque às vezes recrutamos as pessoas erradas. Há vários erros comuns que cometemos: Recrutamos somente aquelas pessoas que são como nós – pessoas que se harmonizam com nossa própria personalidade ou estilo de ministério. Ignoramos o inconformista ou o revolucionário, que é mais difícil de ser treinado, mas que poderia evangelizar nações. Deixamos de lado a pessoa criativa e intuitiva, que é fraca em administração, mas que alcançaria pessoas de maneiras que jamais pensamos. Recrutamos a pessoa dinâmica, o jovem superstar expansivo e não a pessoa de caráter e conteúdo genuínos. Recrutamos apenas para um tipo de ministério – geralmente, a forma tradicional de ministério em nossa denominação – em vez de começarmos com uma pessoa talentosa e piedosa e de pensarmos que tipo de ministério poderia ser desenvolvido em torno dela. Não deixamos as pessoas escaparem da caixa em que as colocamos; não permitimos que elas superem as primeiras impressões que temos a seu respeito. Esperamos demais para recrutar certas pessoas, e elas acabam tomando decisões familiares ou profissionais que fecham as opções de ministério. Independentemente de quem você recrute, uma verdade árdua precisa ser encarada: recrutar pessoas para o ministério, treiná-las como aprendizes e mandá-las para a faculdade bíblica resultará, inevitavelmente, na saída de seus melhores e mais talentosos membros de igreja. Isto é um desafio para o seu amor pelo evangelho. Em que você está mais interessado: no crescimento de sua própria congregação ou no crescimento do reino de Deus? Está comprometido com o crescimento da igreja ou com o crescimento do evangelho? Você quer mais membros nos bancos da igreja agora ou mais trabalhadores para a seara nos próximos 50 anos? Em teoria, é fácil darmos a resposta correta. Mas a fé sem obras é morta. Demonstramos nossa confiança no poder do evangelho e no reino universal de Cristo, quando continuamos a empurrar nossos melhores e mais brilhantes ovens para fora, para a obra do evangelho. A coisa maravilhosa a respeito da generosidade é que Deus a ama e a abençoa. Em nossa experiência, aquelas igrejas que não tentam segurar seus membros, mas sempre os treinam e os exportam generosamente para treinamento posterior e ministério em outros lugares, são igrejas que Deus abençoa com mais e mais pessoas novas para serem treinadas. A mentalidade de treinamento é um mecanismo de crescimento e dinamismo. Multiplica o ministério porque multiplica os ministros. Gera e desenvolve continuamente discípulos que fazem discípulos – tanto dentro de nossa própria igreja como no mundo afora – para a glória do Senhor Jesus, cuja autoridade se estende sobre todos até ao fim dos séculos.$conteudo$
    )
    returning id into v_aula_id;

    insert into public.atividades (aula_id, ordem, pergunta, tipo, razao) values
    (v_aula_id, 1, $p$O aprendizado ministerial de dois anos testa o caráter do aprendiz onde a sala de aula não alcança, expondo a lacuna entre a imagem e a realidade nas pressões da vida ministerial. Refletindo sobre seu próprio caminho até aqui, em que área do seu caráter você ainda precisaria ser 'testado de perto' por alguém mais experiente, e quem hoje conhece a sua realidade e não apenas a sua imagem?$p$, 'reflexao', null),
    (v_aula_id, 2, $p$Os autores admitem que muitas vezes recrutamos as pessoas erradas: só quem é como nós, o jovem expansivo em vez da pessoa de caráter genuíno, ou ignorando o inconformista difícil de treinar que poderia evangelizar nações. Qual desses erros você percebe que tem cometido, e quem você pode ter deixado de fora da caixa em que o colocou?$p$, 'reflexao', null),
    (v_aula_id, 3, $p$O capítulo confronta o leitor com uma verdade árdua: treinar e exportar os melhores membros significa perdê-los para a obra em outros lugares, e pergunta se você está mais interessado no crescimento da sua congregação ou no crescimento do reino. Seja honesto: o que dentro de você resiste a empurrar seus jovens mais talentosos para fora, e como esse apego revela em que você realmente confia?$p$, 'reflexao', null);
  end if;

  -- ---------------------------------------------------------------
  -- Capítulo 12 — Começando  (aula ordem = 12)
  -- ---------------------------------------------------------------
  select id into v_aula_id from public.aulas
  where curso_id = v_curso_id and ordem = 12;

  if v_aula_id is null then
    insert into public.aulas (curso_id, titulo, ordem, conteudo)
    values (
      v_curso_id,
      $t$Capítulo 12 — Começando$t$,
      12,
$conteudo$Agora, temos a impressão de que começamos algum tempo atrás com uma videira, uma treliça e a Grande Comissão. E, no início, fizemos uma promessa de que não ofereceríamos nenhuma técnica nova, nenhuma bola mágica e nenhum caminho garantido para o sucesso e o estrelato no ministério. Fizemos isto porque o ministério cristão não é realmente muito complicado. É apenas o fazer e o nutrir genuínos seguidores do Senhor Jesus Cristo por meio da proclamação dedicada da Palavra de Deus, guiada pelo Espírito. É fazer discípulos. Isto não é difícil de entender nem de fazer – a menos, é claro, que você seja uma pessoa pecadora que vive num mundo de pecadores. A tarefa enganosamente simples de fazer discípulos se torna exigente, frustrante e difícil em nosso mundo, não porque ela seja difícil de ser compreendida, mas porque é difícil perseverarmos nela. Esta é a razão porque corremos atrás do mais recente perito em ministério que sempre tem feito uma igreja crescer do nada para, no mínimo, 5.000 pessoas. A cada cinco ou dez anos, uma nova onda aparece. Pode ser o modelo de culto para interessados, ou o modelo de igreja com propósito, ou o modelo de envolvimento cultural em missões ou qualquer outra nova moda. Todas estas metodologias têm coisas boas a seu favor, mas todas estão igualmente aquém do objetivo real – porque nosso alvo não é fazer igrejas crescerem, e sim fazer discípulos. Vamos reunir nossos pensamentos com as seguintes proposições:

1. Nosso alvo é fazer discípulos O alvo do ministério cristão não é aumentar o auditório no domingo, fortalecer o papel da membresia, ter mais pessoas nos pequenos grupos ou expandir o orçamento (por mais importantes e valiosas que estas coisas sejam!). O alvo fundamental é fazer discípulos que fazem outros discípulos, para a glória de Deus. Queremos ver pessoas convertidas da morte em ofensas e pecados para a vida em Cristo; e, uma vez convertidas, que sejam acompanhadas e firmadas como discípulos maduros de Jesus; e, quando se tornarem firmes, que sejam treinadas em conhecimento, piedade e habilidades para que, por sua vez, façam discípulos de outros. Esta é a Grande Comissão – fazer discípulos. O padrão de uma igreja florescente é que ela esteja fazendo discípulos genuínos, que, por sua vez, façam discípulos de Jesus Cristo.

2. As igrejas tendem em direção ao institucionalismo como as faíscas voam para cima Igrejas se movem inevitavelmente em direção ao institucionalismo e à secularização. O foco muda da videira para a treliça – de ver pessoas crescendo como discípulos para organizar e manter programas e atividades. Como pastores, chegamos a pensar somente em termos de estrutura e coletividade. Desgastamo-nos no envolver pessoas em pequenos grupos, aumentar os números de pessoas em vários programas, criar eventos aos quais pessoas possam vir e assim por diante. Paramos de pensar e orar sobre as pessoas e o ponto em que cada uma está no crescimento evangélico e nos focalizamos, em lugar disso, em conduzir grande número de atividades – cuja frequência (presumimos) equivalerá a crescimento em discipulado. No entanto, participar de grupos e de atividades não produz crescimento em discipulado, assim como o ouvir o Sermão do Monte não torna uma pessoa em discípulo de Jesus. Muitos daqueles que acompanharam Jesus e o seguiram em diferentes tempos não eram discípulos genuínos. As multidões se aglomeravam ao redor dele por muitas razões, mas logo se afastavam dele novamente.

3. A essência do fazer discípulos é o ensino diligente A palavra “discípulo” significa, antes de tudo, “aprendiz” ou “pupilo”. É assim que nos tornamos discípulos e crescemos como discípulos: ouvindo e aprendendo a Palavra de Cristo, o evangelho, e aplicando sua verdade ao nosso coração pelo Espírito Santo. A essência da obra de videira é o falar diligente, guiado pelo Espírito, a mensagem da Bíblia, uma pessoa para outra (ou para mais do que uma). Várias estruturas, atividades, eventos e programas podem prover um contexto em que este falar diligente pode acontecer, mas sem o falar é tudo treliça e não videira.

4. O alvo de todo o ministério – não apenas da obra de pessoa a pessoa – é nutrir discípulos Não existem estruturas ou contextos específicos para discipular. Em alguns lugares, o “movimento de discipulado” tem mudado a linguagem de fazer discípulos para dar a entender que somente o acompanhamento um a um constitui o verdadeiro fazer discípulos e que reuniões da igreja, pequenos grupos e outras reuniões coletivas não equivalem a fazer discípulos. O alvo de todo o ministério cristão, em todas as suas formas, é fazer discípulos. O sermão no domingo deve almejar fazer discípulos, bem como o pequeno grupo que se reúne às terças-feiras à noite, o café da manhã de homens que acontece uma vez por mês e a reunião informal de amigos cristãos que acontece nos sábados à tarde. Nestas questões, as igrejas tendem a oscilar para um extremo ou outro. Quando escrevemos isto, na maioria das igrejas que conhecemos e visitamos, o problema é que não há quase qualquer trabalho pessoal acontecendo, e os que constituem a equipe pastoral gastam seu tempo em organizar e administrar, em vez de procurar, discipular e treinar pessoas. Eles mesmos gastam pouco tempo com o treinamento de pessoas, e essas pessoas, por sua vez, gastam pouco tempo se reunindo para treinamento de outras pessoas. O foco mudou de pessoas e seu crescimento como discípulos para atividades, eventos e crescimento em números.

5. Ser um discípulo é ser um fazedor de discípulos Jesus deu a seus discípulos uma visão para fazerem discípulos em todo o mundo. Nenhum lugar da criação está fora dos limites, e nenhum discípulo está isento da obra. Esquivamo-nos naturalmente do caráter radical deste desafio. Esta definição substitui nossa agradável e cômoda visão da “ótima vida cristã” por uma chamada para todos os cristãos dedicarem sua vida a fazer discípulos de Jesus. “Fazer discípulos” é uma expressão realmente útil para resumir esta chamada radical, porque abrange tanto alcançar os não cristãos quanto encorajar os irmãos na fé a crescerem em Cristo. Como Mateus 28 diz, fazer discípulos é batizar pessoas em Cristo, e ensiná-las a obedecer a tudo o que Jesus ordenou. Fazer discípulos, portanto, se refere a uma enorme gama de relacionamentos, conversas e atividades – tudo desde pregar um sermão a ensinar numa classe de escola dominical; desde conversar com um vizinho não cristão na cerca do quintal a escrever um bilhete de encorajamento para um amigo cristão; desde convidar um membro da família para ouvir o evangelho na igreja a reunir-se com um irmão em Cristo para estudarem a Bíblia juntos; desde ler a Bíblia para seus filhos a fazer um comentário cristão no cafezinho no escritório. 6. Fazer discípulos precisa ser treinado e equipado com convicção, caráter e competência Se esta visão de fazer discípulos está correta, uma parte integral de fazer discípulos é ensinar e treinar cada discípulo a fazer outros discípulos. Este treinamento não é apenas a transmissão de certas técnicas e habilidades. Envolve nutrir e ensinar pessoas em seu entendimento e conhecimento (suas convicções), em sua piedade e maneira de viver (seu caráter) e em suas habilidades e experiência prática de ministrar aos outros (sua competência). Este tipo de treinamento se parece mais com paternidade do que com sala de aula. É relacional e pessoal e envolve modelação e imitação. Para a maioria das igrejas e dos ministros, pensar em treinar desta maneira exigirá diversas “mudanças de mentalidade” quanto ao ministério – desde conduzir programas e eventos a focalizar-se em pessoas e treiná-las; desde trabalhar com pessoas a fazer outras pessoas crescerem; desde manter estruturas a treinar novos fazedores de discípulos.

7. Há apenas uma classe de discípulos, apesar dos diferentes papéis e responsabilidades Todos os cristãos devem ser fazedores de discípulos e devem buscar o crescimento da videira, sempre e como puderem. Contudo, entre a variedade de dons e papéis que cristãos diferentes têm nesta tarefa, alguns têm responsabilidade específica como pastores, supervisores e presbíteros, para ensinar, advertir, repreender e encorajar. Estes são os diretores e organizadores da visão de fazer discípulos de Cristo, os guardiões e mobilizadores, os mestres e modelos. Pastores, presbíteros e outros líderes proveem as condições sob as quais o resto da congregação pode dar continuidade à obra de videira – por falarem diligentemente a verdade de Deus aos outros. Em um nível profundo, todos os pastores e presbíteros são apenas ogadores no time. Não têm uma essência ou um status diferente, nem uma tarefa essencialmente diferente – como se fossem os jogadores, e o restante da congregação fossem espectadores ou equipe de apoio. Um pastor ou presbítero é um dos trabalhadores de videira que recebeu uma responsabilidade específica para cuidar do povo e equipar os membros da igreja para serem fazedores de discípulos.

8. A Grande Comissão, com seu imperativo de fazer discípulos, precisa instigar uma nova maneira de pensar sobre nossas reuniões de domingo e sobre o lugar do treinamento na vida da congregação O que obstrui a visão de fazer discípulos, dada por Cristo, nas igrejas cristãs? Na maioria dos casos, não é a falta de pessoas para serem treinadas nem a ausência de não cristãos para serem alcançados, mas padrões e tradições que restringem a vida da igreja. Estes obstáculos podem ser denominacionais e de longa existência. Ou podem ser o resultado da adoção da tendência mais recente de crescimento de igreja. Podem estar na mente do pastor, ou na mente das pessoas, ou – mais provavelmente – na mente de ambos. Se o alvo de nosso ministério é fazer discípulos, então muitas igrejas (e seus pastores) precisarão fazer uma reconsideração do que estão procurando atingir em suas reuniões de domingo e de como isso se relaciona com outras atividades de ministério durante o resto da semana. Isto pode significar começar coisas novas, porém, muito frequentemente, significará o encerramento de estruturas e programas que não servem mais, eficientemente, ao alvo de fazer discípulos. Pode significar a remoção de atividades e eventos regulares, de modo que a congregação tenha tempo para realizar alguma obra de fazer discípulos – reunirem-se com amigos não cristãos, reunirem-se individualmente com novos frequentadores da igreja e assim por diante. Pode significar uma revolução na maneira como a equipe de liderança da igreja vê seu ministério – não atuando como provedores de serviços ou como gerentes, mas como treinadores. 9. Treinar quase sempre começa pequeno e cresce, à medida que os trabalhadores se multiplicam A tentação envolvida em treinar é sempre começarmos um novo programa – realizarmos uma multidão de cursos de treinamento e, por meio deles, impactarmos o maior número de membros da congregação quanto possível. Aplicamos nossa mentalidade gerencial baseada em estruturas e eventos à tarefa de treinar e tentamos fazer isso em larga escala e de modo eficiente. Mas não podemos realmente treinar pessoas desta maneira, como não podemos exercer a paternidade desta maneira. Treinar é algo pessoal e relacional e exige tempo. Envolve compartilhar não somente habilidades, mas também conhecimento e caráter. Envolve imitação e ser modelo. Cursos de treinamento e outros recursos são ferramentas muito úteis que nos ajudam nesta tarefa. Podem nos fazer economizar muito tempo (porque não teremos nós mesmos de elaborar e aprimorar conteúdos de treinamento) e podem oferecer excelentes estruturas nas quais a obra relacional e pessoal de treinar pode acontecer. Mas o treinamento deve começar com pessoas e focalizar-se em pessoas – não em programas. Em outras palavras, se queremos começar a treinar discípulos para serem fazedores de discípulos, precisamos formar uma rede de ministério pessoal em que pessoas treinam pessoas. E isso só poderá começar se escolhermos um grupo de prováveis candidatos e começarmos a treiná-los como cooperadores. Este grupo trabalhará ao nosso lado, e, em algum tempo, eles mesmos se tornarão treinadores de outros cooperadores. Alguns de nossos cooperadores atingirão seu potencial e se tornarão colegas de trabalho e fazedores de discípulos frutíferos. Outros não. Mas não podemos evitar isso. Construir um ministério baseado em pessoas e não em programas é inevitavelmente tumultuado e consome tempo.

10. Precisamos desafiar e recrutar a próxima geração de pastores, mestres e evangelistas Quando a máquina de treinamento começa a funcionar, e pessoas dentro de nossa congregação são mobilizadas a ministrar aos outros, algumas pessoas “que vale a pena observarmos” surgirão – pessoas de convicções, caráter e competências fortes. Estas pessoas são os potenciais “trabalhadores do evangelho reconhecidos” da próxima geração. E, se você é um pastor ou presbítero, uma de suas responsabilidades dadas por Deus é reconhecer estes homens, nutri-los e treiná-los e confiar-lhes o evangelho, os quais, por sua vez, serão “fiéis e também idôneos para instruir a outros” (2 Tm 2.2). Muitas igrejas têm achado que um programa de aprendizado ministerial é uma maneira muito eficiente de promover este processo (como o programa desenvolvido e apoiado pelo Ministry Training Strategy (Estratégia de Treinamento Ministerial).

COMEÇANDO

Esperamos que a leitura deste livro tenha deixado sua mente zunindo com ideias e desafios para o ministério em que você está envolvido. Contudo, frequentemente é muito difícil traduzir uma mente repleta de ideias para um conjunto de alvos e ações concretos. Para ajudá-lo a pensar e planejar, sugerimos aqui um plano para você começar a remoldar seu ministério em torno de pessoas e de treinamento, em vez de programas e eventos.

Passo 1: Estabeleça a agenda nos domingos Se você quer mudar a cultura na direção de fazer discípulos e de treinamento, esta nova direção precisa moldar suas reuniões regulares aos domingos. Você poderia, por exemplo, pregar uma série de sermões sobre “O que é crescimento evangélico?” ou sobre “Discípulos e fazer discípulos”. Você pode expor a visão bíblica da Grande Comissão e como ela resulta em discípulos que fazem outros discípulos. No entanto, mais do que isso, em sua exposição regular das Escrituras: mostre como o evangelho da graça modela uma vida de louvor e de sacrifício por Cristo. entusiasme a congregação com os grandes propósitos eternos de Deus em fazer discípulos e formar uma comunhão de discípulos sob o senhorio de Cristo. chame a congregação ao discipulado radical. comunique a expectativa de que as coisas que estão sendo ensinadas do púlpito devem também ser transmitas a outros (você pode oferecer resumos ou perguntas de discussão para uso em ministério pessoal). pregue de uma maneira que ensine a igreja a entender a Bíblia e a comentá-la entre eles mesmos; mostre-lhes como você chegou às suas conclusões com base no texto exposto. aborde questões apologéticas e pastorais que serão úteis não apenas para os presentes, mas também para outros por meio do ministério pessoal dos presentes. Não é apenas o sermão que estabelece a agenda e começa a mudar a cultura da congregação. Nas reuniões de sua igreja, traga membros à frente para compartilharem fatos sobre os ministérios em que estão envolvidos. Não traga apenas superestrelas e histórias de sucesso. Ofereça exemplos para a congregação de pessoas que estão saindo de sua zona de conforto e tentando algo novo. Isto também flui para os assuntos pelos quais oramos em nossas reuniões. Faça dos vários ministérios pessoais dos membros da congregação um assunto regular para as orações coletivas. Também podemos desenvolver uma cultura de treinamento na maneira como as pessoas contribuem para o culto. Ofereça treinamento e ouça o retorno daqueles que participam do culto – na música, na leitura bíblica, nas orações, no compartilhar um testemunho, na recepção de novos frequentadores e assim por diante. Passo 2: Ande perto de seus presbíteros ou conselho espiritual Ao construir uma ênfase em treinamento e em fazer discípulos na sua igreja, é vital que os presbíteros e os líderes existentes sejam totalmente incluídos no pensamento, planejamento e tomada de decisões. Eis um exemplo de como um pastor fez isso:

Ao introduzirmos a Estratégia de Treinamento Ministerial na Christian Reformed Churches of Australia (CRCA), não podemos esquecer que estas igrejas são governadas por um sistema de presbíteros em cada congregação. Todas as decisões sobre a vida e a direção da igreja são tomadas pelos presbíteros que formam o conselho da igreja. Por isso, quando Colin Marshall me convidou a fazer seu curso Arte de Treinamento Ministerial [um precursor deste livro], eu sabia que teria de obter a concordância da minha equipe de presbíteros. Pedi a Colin permissão para fazer fotocópias das leituras designadas no curso, a fim de compartilhar com meus presbíteros. Tornou-se necessário que eu fizesse as leituras antes de cada reunião do conselho, e, depois, nós as discutíamos na primeira meia hora da reunião. Fiz isso durante aquele ano, para que, ao terminar o curso, os presbíteros tivessem também feito algumas leituras. Havendo terminado o curso e estando muito interessado nele, perguntei aos presbíteros o que eles pensavam. Eles concordaram em que o curso seria parte do que faríamos como igreja. O fato importante no modo como introduzimos o curso foi que os presbíteros me acompanharam na ideia. Tiveram tempo para assimilar todas as novas ideias. Tiveram tempo para refletir e assimilá-lo, de modo que, ao perguntar-lhes, no final do ano: “Nós o faremos?”, estavam prontos para seguir em frente. É muito importante dar aos seus líderes tempo para processarem a ideia, concordarem com ela e tomarem-na para si. Digo isto porque meus colegas não tomaram os passos que tomei, e, quando o apresentaram ao conselho de sua igreja local, muitos encontraram resistência a estas “novas ideias”. Vários colegas me pediram que falasse aos seus presbíteros, e gastei uma noite naquelas igrejas explicando os principais conceitos do treinamento ministerial. Fiquei feliz por ver “a luz acendendo” para alguns dos presbíteros mais velhos, que encorajam seus pastores a estabelecer o treinamento em suas igrejas. Na CRCA, este processamento por meio dos presbíteros precisa ser uma coisa permanente, visto que cada um de nossos presbíteros serve por um mandato de três anos. Eu treino todos os meus presbíteros por seis meses. Este processo de treinamento e os quatro seminários que realizamos sobre o que é a Estratégia de Treinamento Ministerial e como ela funciona os tem deixado entusiasmados quanto à mentalidade de treinamento, quando são indicados como líderes da igreja. Ver homens jovens sendo treinados em pregação, líderes de estudos bíblicos, e aprendizes adquirindo as habilidades do ministério, tem dado aos presbíteros o senso de que somos uma igreja que treina; é parte de nosso DNA agora. Tudo é uma questão de mentalidade: “este é o modo como somos igreja”. É sermos fiéis ao mandato de fazer discípulos e de equipar os santos para a obra do ministério. É o que precisamos fazer se queremos pastores, evangelistas e líderes agora e para o futuro.

Estabelecer alguma forma de treinamento e a “conversa ministerial” constante na agenda das reuniões regulares do conselho da igreja é muito proveitoso. Com o passar do tempo, isso solidifica o corpo de presbíteros como cooperadores no evangelho e não como um conselho de reguladores e de responsáveis pela igreja. Decisões são tomadas pelo prisma do crescimento do evangelho. Com o passar do tempo, podemos também criar a expectativa de que ser um presbítero ou conselheiro espiritual também significa estar engajado em algum ministério pessoal da Palavra – visitar os novos frequentadores, reunir-se individualmente com outras pessoas, orientar indivíduos que têm o potencial para serem futuros líderes. O alvo geral é aumentar a unidade em torno da tarefa comum da obra do evangelho.

Passo 3: Comece a formar uma nova equipe de cooperadores O princípio é: faça uma obra profunda na vida de poucas pessoas. Este é o grupo de irmãos e irmãs que morreriam juntos por causa do evangelho, aqueles com os quais você compartilhará sua vida e ministério, na expectativa de que eles aprenderão a evangelizar, ensinar e treinar outros. Observe que esta é uma nova equipe. Não pense apenas naqueles que estão servindo em ministério ou em comissões. Escolha uma mistura de líderes atuais e líderes futuros, com os quais você gostaria de construir o ministério nos próximos cinco anos. Lembre: você não está recrutando pessoas para preencher lacunas no programa de sua igreja; e, sim, treinando cooperadores ao redor dos quais edificará o ministério de acordo com os dons e as oportunidades específicas deles. Algumas destas pessoas começarão novos empreendimentos na evangelização ou no crescimento cristão – coisas que você ou elas ainda não tinham imaginado ou pensavam que seriam possíveis. Treinar esta equipe de cooperadores pode ser realizado por meio de reuniões individuais, reuniões de grupos ou, mais frequentemente, um mistura de ambas e inclui a nossa agora familiar mistura dos três “Cs” (convicção, caráter e competência). Quanto a mais ideias sobre como treinar uma equipe de cooperadores, ver o capítulo 9.

Passo 4: Procure definir com seus cooperadores como o fazer discípulos crescerá em seu contexto Então, você está treinando uma equipe de cooperadores – mas, como o fazer discípulos se desenvolverá a partir desta base? Como se multiplicará? Não há, de fato, uma resposta correta, porque isso depende dos dons e das circunstâncias de seus cooperadores, bem como da igreja ou do contexto de ministério em que você está trabalhando. Eis apenas uma ideia para manter as coisas fluindo. A sua congregação talvez já tenha uma rede de grupos de estudos bíblicos que funciona razoavelmente bem, mas o desafio real que você tem agora é ajudar novas pessoas (cristãos ou não cristãos) a se integrarem à vida da congregação e a serem discipuladas. Portanto, você trabalha com seus cooperadores num ministério de visitas e acompanhamento direcionado especialmente para os novos frequentadores. O alvo é que todo novo frequentador ou visitante da igreja seja visitado pessoalmente em seu lar e, depois, acompanhado durante os seis meses seguintes, até ao tempo em que ele esteja segura e alegremente envolvido num grupo pequeno (no qual o líder do grupo assume a responsabilidade de discipulá-lo). Seus cooperadores são a linha de frente em fazer acontecer este processo de integração. Você os leva consigo para visitar novos frequentadores da igreja e os treina em como avaliar o nível em que eles estão no crescimento evangélico. Cada cooperador pode tomar pessoalmente dois ou três novos frequentadores por um período de três meses: para se reunir individualmente com eles várias vezes, evangelizálos, se ainda não são crentes, ler a Bíblia e orar com eles, explicar a visão da igreja e como envolver-se, levá-los para almoçar e apresentá-los aos membros da congregação, telefonar para eles quando não vêm à igreja, para saber como estão passando e cuidar que se unam a um pequeno grupo. Há muitos recursos disponíveis para ajudar um cooperador a reunir-se com novos frequentadores e ministrar-lhes um a um. Há ferramentas de estudos bíblicos para compartilhar o evangelho com alguém, ou para estabelecer alguém nas verdades básicas da fé e da vida cristã, ou apenas para ler a Bíblia individualmente com outra pessoa. Há também materiais excelentes para ajudá-lo a treinar cooperadores nestas habilidades de ministério. Ora, esta ideia só funcionará a longo prazo se os pequenos grupos estiverem funcionando bem – e, em especial, se os líderes dos grupos tiverem sido treinados a verem a si mesmos não apenas como facilitadores ou organizadores, mas também como fazedores de discípulos e “minipastores” das pessoas de seu grupo. Gastar tempo regular com seus líderes de grupos para treiná-los desta maneira pode ser a sua próxima prioridade.

Passo 5: Realize alguns programas de treinamento Embora tenhamos enfatizado que a necessidade de treinamento é pessoal – ao contrário de apenas guiar pessoas num curso de três semanas – há muitas vantagens em realizar programas de treinamento estruturados ou padronizados. Eles não somente oferecem um nível de estrutura formal que pode aprimorar a qualidade do treinamento, mas podem também funcionar como o primeiro passo para a identificação de pessoas que são adequadas para mais responsabilidade e mais treinamento pessoal intensivo. Por exemplo, você poderia encorajar todos os pequenos grupos a fazerem um curso sobre evangelização em seu tempo normal de grupo – Seis Passos ara Falar sobre Jesus ou Duas Maneiras de Viver: Conhecer e Compartilhar o Evangelho. Isto dará a todo o grupo, não importando o seu nível de crescimento ou os seus dons, certa medida de habilidade e confiança em serem capazes de falar sobre sua fé. No entanto, realizar um curso como este revelará pessoas que são realmente boas em evangelização e que estão prontas para treinamento e ministério posterior nesta área.

Passo 6: Fique atento a “pessoas que vale a pena observarmos” À medida que cresce o número de pessoas engajadas em treinamento e ministério, fique atento àqueles que têm verdadeiro potencial. Convide um ou dois deles para um aprendizado ministerial de dois anos. O alvo de longo prazo pode ser o de enviar estes aprendizes para fazer um treinamento formal posterior e, depois, retornar à congregação para trabalhar ao seu lado ou para plantar uma nova igreja com o seu apoio. À medida que mais e mais pessoas são treinadas como fazedores de discípulos, mais e mais pessoas são contatadas, evangelizadas e/ou acompanhadas. A quantidade de trabalho com pessoas prolifera gradualmente. E a necessidade por pastores, líderes, supervisores e presbíteros cresce de acordo com isso. O número de obreiros pagos em sua congregação precisará crescer, apenas para se adequar ao número crescente de pessoas que devem ser lideradas e pastoreadas.

Por favor, lembre: isto é apenas um conjunto de ideias sobre como começar. Seu ministério e seu contexto produzirão suas próprias variações e desafios. Quando você começa a introduzir estes conceitos em sua congregação, tenha o cuidado de continuar pregando o evangelho do perdão gratuito por meio de Jesus e a vida de obediência que resulta do evangelho. Continue a exaltar a morte e a ressurreição de Cristo e a orar por seu povo. A motivação de servir e de ser treinado procede do evangelho e de uma obra profunda do Espírito no coração das pessoas. Não vem de você insistir em treinamento e de importunar as pessoas até que elas finalmente se submetam a fazê-lo! É graça e não culpa. Não faça do “treinamento” o novo critério de verdadeiro discipulado. No entanto, as possibilidades de treinamento e crescimento na maioria das igrejas são infinitas e altamente empolgantes. E você precisará refletir por si mesmo nas possíveis mudanças radicais que precisam acontecer. Para ajudá-lo a fazer isso e como um meio útil de concluir, podemos fazer um pequeno experimento mental.

IMAGINE ISTO...

Enquanto escrevemos, os primeiros sinais inquietantes de uma gripe suína pandêmica estão se tornando notícia importante ao redor do mundo. Imagine que a pandemia está atingindo sua parte do mundo e que todas as reuniões públicas com mais de três pessoas foram proibidas pelo governo por razões de segurança e saúde pública. E digamos que, por causa de algumas combinações catastróficas de circunstâncias locais, esta proibição tem de permanecer em vigência por 18 meses. Como sua congregação de 120 membros continuaria a funcionar – sem nenhuma reunião regular de qualquer tipo e sem grupos nos lares (exceto os de três pessoas)? Se você fosse o pastor, o que faria? Penso que você poderia mandar cartas e e-mails regularmente aos membros de sua igreja. Poderia fazer ligações telefônicas e, talvez, até fazer uma mensagem em arquivo de áudio. Mas como a obra constante de ensino, pregação e pastorado aconteceria? Como a congregação seria encorajada a perseverar em amor e boas obras, especialmente em tais circunstâncias? E o que faria a respeito da evangelização? Como novas pessoas seriam alcançadas, contatadas e acompanhadas? Não poderia haver cafés da manhã para homens, nenhum café da manhã, nenhum curso evangelístico ou reuniões de evangelização. Nada. Você poderia, é claro, voltar à antiga prática de visitar sua congregação de casa em casa e de bater de porta em porta no bairro para contatar novas pessoas. Mas como um pastor poderia se reunir com 120 pessoas e ensinar todos os adultos em sua igreja? E os filhos deles? Como alcançaria de porta em porta os bairros periféricos? Como daria acompanhamento aos contatos que você teria feito? Ora, se isso tivesse de ser feito, você precisaria de ajuda. Precisaria começar com dez de seus homens cristãos mais maduros e se reunir intensivamente com dois deles de cada vez nos primeiros dois meses (enquanto manteria contato com todos os demais por telefone ou por e-mail). Você treinaria esses dez homens em como ler a Bíblia e como orar com uma ou duas outras pessoas e com seus filhos. O trabalho deles seria duplo: “pastorear” a esposa e seus filhos por meio de leitura bíblica e oração regularmente; e, a cada encontro com quatro outros homens, treiná-los e encorajá-los a fazer o mesmo. Supondo que 80% das pessoas da igreja seriam casadas, por meio destes dez homens e daqueles que eles treinariam subsequentemente, a maioria dos adultos casados seriam envolvidos em encorajamento baseado na Bíblia. Enquanto isso continuasse a acontecer (com você fazendo telefonemas e oferecendo apoio por e-mail durante o processo), você poderia escolher outro grupo para ser treinado pessoalmente – pessoas que poderiam se reunir com solteiros, ou pessoas que teriam o potencial para ir de casa em casa ou para evangelização, ou pessoas que seriam boas em acompanhar os novos contatos. Haveria muito contato pessoal e muitas reuniões um a um nas quais pessoas poderiam se encaixar. Mas, lembre, não haveria cultos a realizar, comissões, conselho espiritual, seminários, grupos nos lares, etc. – de fato, nenhum tipo de atividade ou evento em grupos a organizar, administrar, apoiar ou participar. Haveria apenas ensino e discipulado pessoal e treinamento de pessoas, em turnos, para serem fazedores de discípulos. Eis uma pergunta interessante: depois de 18 meses, quando a proibição fosse removida, e vocês pudessem recomeçar as reuniões aos domingos e todas as demais reuniões e atividades da vida eclesiástica, o que você faria de maneira diferente?$conteudo$
    )
    returning id into v_aula_id;

    insert into public.atividades (aula_id, ordem, pergunta, tipo, razao) values
    (v_aula_id, 1, $p$Os autores afirmam que as igrejas tendem ao institucionalismo 'como as faíscas voam para cima', deslocando o foco da videira (pessoas crescendo como discípulos) para a treliça (manter programas e contar números). Avaliando sua semana real de ministério, quanto do seu tempo tem sido gasto organizando atividades versus procurar, discipular e treinar pessoas individualmente?$p$, 'reflexao', null),
    (v_aula_id, 2, $p$O plano de 'Começando' sugere formar uma nova equipe de cooperadores fazendo 'uma obra profunda na vida de poucas pessoas', e não recrutar gente apenas para preencher lacunas no programa. Se você escolhesse hoje esse pequeno grupo com quem construiria o ministério nos próximos cinco anos, quem estaria nele, e por que essas pessoas e não as que apenas preenchem funções vagas?$p$, 'reflexao', null),
    (v_aula_id, 3, $p$No experimento mental em que toda reunião pública é proibida por 18 meses, sobraria apenas ensino, discipulado pessoal e treinamento de pessoas para serem fazedores de discípulos. Se isso acontecesse com a sua congregação amanhã, o que desmoronaria por depender só de estruturas, e o que essa pergunta revela sobre onde você tem realmente colocado seu peso como pastor?$p$, 'reflexao', null);
  end if;

  -- ---------------------------------------------------------------
  -- Apêndice — Perguntas frequentes e respostas  (aula ordem = 13)
  -- ---------------------------------------------------------------
  select id into v_aula_id from public.aulas
  where curso_id = v_curso_id and ordem = 13;

  if v_aula_id is null then
    insert into public.aulas (curso_id, titulo, ordem, conteudo)
    values (
      v_curso_id,
      $t$Apêndice — Perguntas frequentes e respostas$t$,
      13,
$conteudo$Quando compartilhamos estas ideias com muitas pessoas no decorrer dos anos, várias perguntas surgiram. Eis algumas das mais comuns:

1. Você diz que todo cristão é chamado a ser um “trabalhador de videira” e um “discípulo que faz discípulos”. Não sou bom em ensinar e falar; e acho que não sei muito sobre a Bíblia. Como posso realizar a chamada da qual você está falando? Talvez a melhor maneira de responder isto seja mencionar a conversa que tive recentemente como amigos cristãos que trabalhavam com vendas – um, vendia imóveis, o outro, software. Disse aos meus amigos que às vezes acho difícil falar com facilidade sobre as verdades cristãs, especialmente com não cristãos, porque não tenho um tipo natural de personalidade de “vendedor” – não como eles. Mas um deles logo me interrompeu. “Não, você não entende sobre vendas”, ele disse. “Vender não depende de uma personalidade específica ou de alguém ter boa lábia. Tenho muitos homens trabalhando para mim que se julgam grandes vendedores porque são homens de ‘vendas’ ambiciosos e eloquentes. Mas não são realmente os melhores vendedores. A moça que está fazendo os maiores negócios está muito mais na retaguarda, mas ela é genuína. Ela transmite real interesse e sinceridade, fica perto das pessoas, as ouve e as entende e, depois, trabalha com empenho para ajudá-las a terem o que querem. Ela está fechando mais e mais negócios, mas, se você lhe perguntasse, ela não diria que é uma vendedora natural.” “Vender está ligado realmente a se você ama o produto, se o conhece bem e se você se preocupa com as pessoas e quer vê-las satisfeitas. Se você crê realmente no produto, você o venderá.” Meu outro amigo vendedor também entrou na conversa nesta altura. “Sim. Está certo. Você pode ter alguém que conhece perfeitamente os detalhes técnicos do produto, mas que não tem paixão por ele, nenhuma empatia ou habilidade para se relacionar com pessoas e ouvi-las. Vender está muito mais ligado a ouvir do que a qualquer outra coisa.” A lição aqui é que, embora todos nós tenhamos dons e habilidades diferentes, o fator mais importante é quanto amamos a mensagem de Deus e quanto amamos todas as pessoas ao nosso redor que precisam ouvi-la. Você pode não ser a pessoa que vai pregar a multidões ou liderar grupos de estudos bíblicos, mas, se realmente anseia ver pessoas se tornando discípulos de Jesus, então achará meios de fazer isso com os dons que Deus lhe deu – como Dave, o jovem esquizofrênico mencionado no capítulo 2.

2. Sou um pastor e estou convencido, por seu argumento, de que a longo prazo treinar pessoas não somente beneficiará o ministério, mas também me ajudará no uso de meu tempo. Mas quase não tenho tempo para fazer estas coisas agora! Como devo começar? A primeira coisa a dizer é que “treinar” é realmente uma mudança de mentalidade e não apenas um novo conjunto de responsabilidades ou tarefas. Treinar é, em sua maior parte, relacional e feito no trabalho. É o tipo de coisa que pode permear todos os diferentes aspectos de seu ministério, em vez de ser um programa extra, acrescentado ao seu planejamento. Então, quando você visitar um novo frequentador da igreja ou um membro de sua congregação, leve alguém em sua companhia. Quando estiver preparando seus sermões, gaste parte do tempo falando sobre os assuntos com um cooperador (isso ajudará a você e a ele!). Tanto quanto possível, inclua outros no que você está fazendo e os treine, à medida que prossegue. Deixe-os vê-lo em ação, sobre o que você pensa, como reage, e como está usando a Bíblia para influenciar a tarefa que está realizando. Em segundo, faça uma avaliação honesta e completa de como você gasta seu tempo. Quais são as atividades, programas e prioridades que o impedem de dedicar algum tempo especificamente ao treinamento? Há boas razões para estas coisas serem mais prioritárias do que o treinamento? Ou as razões se originam de motivações impróprias – por exemplo, um desejo de satisfazer as expectativas dos membros, ansiedade por bom desempenho na pregação (que leva a preparação excessiva), temor de não cumprir o esperado, insegurança pessoal ou coisas como estas? Em terceiro, adote uma visão de longo prazo. Talvez pareça que não há tempo agora para treinar pessoas por causa de sua grande carga de trabalho, mas deixar de treinar pessoas o fechará permanentemente na armadilha de grande carga de trabalho. Talvez você ache que há muito a fazer e nenhum tempo para realizar treinamento e, por isso, não o realiza. Mas isto significa que você não está levantando ajudantes e cooperadores que possam trabalhar ao seu lado no ministério. E, assim, você continua a levar a carga de trabalho e a se estressar sozinho, o que, com o passar dos anos, o levará à fadiga. Você acaba se tornando vítima de uma vida reativa e do planejamento de curto prazo. Em quarto, seja ousado para dizer “Não” e, por consequência, não ser apreciado. Em muitas situações, dizer “Sim” a mais treinamento significará inevitavelmente dizer “Não” para outras coisas. E, como resultado natural, você enfrentará resistência e sofrerá aversão de algumas pessoas de sua igreja, ou dos oficiais da denominação, ou de ambos. Isto é desagradável, mas inevitável. Nem todos compartilham das prioridades do evangelho. Todavia, neste sentido, desenvolver um conjunto de prioridades, e torná-las públicas, o ajudará bastante, se você trabalhar com empenho para ter junto de si os seus presbíteros e conselho espiritual (ver o passo 2 de “Começando”, no capítulo 12). Talvez não seja necessário dizer isto, mas sofrer aversão e até perder pessoas na igreja não é nosso alvo em si mesmo. Devemos sempre avaliar nossas motivações, ações, apresentações e prioridades quando essas coisas acontecem. Contudo, às vezes precisamos permitir que elas aconteçam a fim de que as prioridades corretas floresçam. Quando as prioridades corretas são mantidas – quando você diz “Não” a algumas pessoas e a algumas coisas – as pessoas não o apreciarão.

3. Os nossos líderes já estão estabelecidos. Ainda devo considerar a utilização do modelo de pastor como treinador? Vários pastores com os quais converso supõem que o treinamento está acontecendo porque realizam certos programas ou têm pequenos grupos implementados. É claro que em certo grau isto pode ser bem verdadeiro. Entretanto, vale a pena avaliar suas práticas correntes com algumas perguntas diagnósticas como estas: Na congregação, há uma cultura de fazer discípulos um a um? Os líderes de estudos bíblicos em sua igreja sabem o que significa pastorear e liderar pessoas em seus grupos? Os seus líderes são norteados por treinamento – ou seja, estão procurando eles mesmos despertar e treinar mais líderes? Todos de sua igreja sabem uma maneira básica de compartilhar a verdade do cristianismo? Todos os membros de sua igreja sabem como encorajar alguém, com e por meio da Palavra de Deus? Todas as pessoas de sua igreja entendem o que significa servir a Jesus e praticam a sua fé cristã na vida diária? Você tem, em sua igreja, um grupo de pessoas que pode ensinar a Bíblia e comunicar bem o principal ensino do texto? Há um grupo de pessoas que entendem as prioridades da igreja e podem treinar outros eficientemente nessas prioridades? Você está identificando, recrutando e treinando aqueles que têm dons para evangelizar (“missionários leigos”) e liberando-os com o evangelho em sua comunidade local? A próxima geração de trabalhadores do evangelho está sendo levantada? Você está vendo o surgimento de novos “talentos para o ministério”? 4. Como posso transmitir uma visão cativante para treinamento ministerial? É importante dar às pessoas um resumo do que você – como um líder de igreja – está fazendo. Como dissemos em todo este livro, queremos que todas as pessoas sejam discípulos que fazem discípulos de Cristo. Você precisará se expressar em sua própria maneira e em termos que funcionam dentro de seu contexto, mas vale a pena dar-se ao trabalho, com seus principais líderes, de elaborar uma declaração que focalize seus alvos. Talvez depois que tiver trabalhado de perto com seus presbíteros ou conselho espiritual, por um ano ou mais, você mesmo poderá estabelecer a tarefa conjunta de reescreverem a visão ou a missão da congregação de uma maneira que sinalize uma mudança de ênfase. Matthias Media, por exemplo, reescreveu recentemente sua declaração de missão, nestes termos:

Queremos persuadir todos os cristãos quanto à verdade dos propósitos de Deus em Jesus Cristo, conforme revelados na Bíblia, e equipá-los com materiais de alta qualidade, para que, pela obra do Espírito Santo eles: 1. dediquem sua vida à honra e ao serviço de Cristo, em santidade e decisões diárias. 2. orem constantemente em nome de Cristo em favor da frutificação e do crescimento do evangelho de Cristo. 3. falem sempre e como puderem a mensagem da Bíblia, que transforma vidas – no lar, no mundo e na comunhão de seu povo.

Como você adaptaria uma declaração como esta para expressar seus alvos de ministério?

5. Por que as pessoas não querem se comprometer? Falta de compromisso por parte dos membros da igreja é talvez a razão mais comum que pastores e líderes apresentam para justificar a falta de treinamento em sua igreja. Ora, não há um remédio simples que cura totalmente este problema. Isto é uma doença fundamentalmente espiritual, mas há vários fatores culturais, teológicos e históricos que contribuem para sua propagação e virulência: Profissionalismo do ministério: em muitas igrejas, os cristãos comuns pensam que o ministério é uma profissão, e, visto que não é a profissão deles, também não é papel deles como cristãos. Os pastores podem se queixar disso, mas eles devem examinar a si mesmos quanto a este assunto. Em muitas igrejas, o ministério é totalmente controlado e centralizado entre os pastores e/ou presbíteros, em parte porque eles gostam disso. Eles têm o controle. As coisas são ordeiras e previsíveis. Mobilizar e liberar a congregação para ministério é empolgante, mas também aumentará inevitavelmente o tumulto e o transtorno. Uma visão clericalizada do ministério: isto é enfatizado em algumas denominações mais do que em outras. A ordenação é uma unção especial em uma pessoa especial para uma obra especial; portanto, os leigos são inclinados a deixar que os ministros ordenados deem continuidade ao ministério. Ministério de nichos: em seu livro Deliberadamente Igreja, Mark Dever argumenta contra funções ministeriais especializadas porque elas tiram da congregação a responsabilidade desses ministérios.1 Se há um ministro de jovens, então a responsabilidade de ministrar aos jovens não está com os pais dos jovens (como deveria), mas com o pastor de jovens. A estrutura age como um desestimulador para as pessoas se envolverem. Imaturidade espiritual: querer servir aos outros e crescer nisso é uma função da maturidade cristã. Quanto mais nos tornamos semelhantes a Jesus, tanto mais queremos gastar nossas vidas em amor e serviço aos outros. Se as pessoas de sua igreja não querem servir, quão eficientemente elas estão sendo ensinadas e discipuladas? Quão eficiente e claramente o próprio evangelho está sendo pregado? As pessoas de sua igreja sabem que dedicar a vida em favor de outros é uma parte integral de ser cristão? Talvez seja tempo de retornar aos fundamentos e desafiar a força do compromisso das pessoas com Jesus como seu Senhor. Talvez seja tempo de rogar a Deus que faça uma obra profunda na vida das pessoas, por meio de seu Espírito, para que elas queiram viver sacrificialmente. Não gastar tempo com as pessoas certas: tendemos a incluir todos em nossas tentativas de treinamento e discipulado. Além disso, tendemos a gastar grande quantidade de nosso tempo com os que são necessitados – como novos frequentadores, os doentes e os que sofrem. Estas pessoas são importantes, mas não são as pessoas ideais em quem devemos investir realmente desde o início. Em vez disso, escolha algumas pessoas – ou mesmo apenas uma pessoa – que amam o crescimento e comece com elas. As pessoas certas nos lugares errados: as pessoas que você gostaria de começar a treinar e com as quais gostaria de trabalhar estão profundamente envolvidas em trabalhos de comissões e outras atividades de “treliça”? Você precisa remover essas pessoas destas estruturas – ou desmontar as estruturas – para que elas tenham tempo e energia para receberem o treinamento. Dons espirituais: pessoas tendem a fazer somente aquilo que elas julgam ter os dons para fazer. “Inventários de dons espirituais” eram muito populares nas igrejas nos anos 1990. Mas fazer todos passarem por uma aula de inventário não ajudou realmente a solucionar o problema de 80/20 (80% do trabalho feito por 20% das pessoas). Por que não? Porque a raiz do problema não é as pessoas não entenderem quais são os seus dons espirituais, e sim a sua motivação e seu entendimento quanto ao ministério. A outra coisa que podemos fazer para motivar a participação no treinamento é trabalhar com munição viva. Ou seja, em vez de apenas dizer: “Quem gostaria de vir e receber um treinamento para o ministério infantil?”, você lança uma visão para um novo clube ou ministério de crianças nas escolas locais. E, quando as pessoas são cativadas pelas possibilidades deste novo ministério, querem se envolver e começar a serem envolvidas. Elas ficarão ansiosas por treinamento. Se tiverem de ficar diante de um grupo de meninos e meninas de 13 anos de idade toda semana para ensinar a Bíblia, ficarão muito desejosas de serem ajudadas, treinadas, equipadas e orientadas de qualquer maneira possível! Afinal de contas, liderança é visão – não é coerção!

6. Na seção “Começando”, estou tendo dificuldades com o passo 3 – ou seja, tenho poucas pessoas que eu poderia treinar como cooperadores. Como posso convencê-las da importância de se envolverem? Como eu as desperto para o desejo de serem treinadas e de ministrarem aos outros? Como este tipo de transformação pessoal acontece de modo que o coração dessas pessoas queime com a vontade de servir a Cristo e a outras pessoas? Como pessoas podem ser transformadas de uma maneira de viver mundana e egoísta (mesmo como cristãos) para uma maneira de servir espiritual e centrada nos outros? Isso só pode acontecer por meio da obra miraculosa de Deus na vida de pessoas, quando ele aplica sua Palavra ao coração delas, por meio do seu Espírito. Como participamos na obra de Deus? Oramos fervorosa e frequentemente pelas pessoas de nossa igreja – para que Deus transforme o coração delas. Ensinamos e aplicamos a Palavra de Deus às pessoas – a partir do púlpito, em pequenos grupos e um a um. Uma maneira de fazer isso seria tomarmos o material dos capítulos iniciais deste livro – em especial, os capítulos 1 a 6 – e o considerarmos com um grupo essencial de pessoas. Você poderia roubar as ideias e transformá-las em estudos ou sermões bíblicos (não nos importamos com isso!). Ou você poderia realmente considerar todo o livro, examinando um capítulo por vez, com discussões e estudo bíblico. Damos às pessoas um gosto para servir aos outros ao levá-las conosco, enquanto fazemos coisas diferentes no ministério. Leve alguém com você para fazer visitas ou bater de porta em porta ou permita que a pessoa o ouça, enquanto faz um estudo bíblico com alguém. Persevere pacientemente. Tudo isto exige tempo, dependendo de quão maduras ou piedosas já são as pessoas de sua igreja. 7. Por que “treinamento” é necessário juntamente com a pregação fiel e o ministério pastoral? Há um instinto bastante correto que diz que, se pregarmos dedicada e fielmente a Palavra de Deus, o coração das pessoas será mudado, e elas quererão se dar à obra de fazer discípulos e ao serviço aos outros. Então, por que precisamos desta coisa separada que chamamos “treinamento”? A resposta é que “treinamento” – como o definimos – não é realmente uma coisa separada porque se conecta com pessoas individualmente. Treinamento não é apenas transmitir certas habilidades. É um ministério da Palavra que leva a crescimento em convicção, caráter e competência. O verdadeiro poder do treinamento está não no método ou na estratégia, mas na maneira como a Palavra de Deus e o Espírito atuam na vida das pessoas. Outra maneira de dizer isso é que “treinamento” é o exercício de ministério pastoral diante de crises. É como você trabalha com pessoas individualmente tendo em vista crescimento e maturidade, quando não as está nutrindo e cuidando delas em suas tristezas, doenças e problemas familiares. A mudança de mentalidade designada “treinamento” também acrescenta uma dimensão à quão bem as pessoas ouvem seu ensino e aprendem dele. Se a cultura permanente de sua igreja é que cada cristão não é apenas um ouvinte, mas também um comunicador, isso muda o modo como eles ouvem. Não há nada como ter de explicar o evangelho para motivar alguém a aprender realmente o que é o evangelho.

8. E quanto à comunidade cristã? Esta conversa sobre “treinamento” não é totalmente individualista? Se o alvo é treinar discípulos que fazem discípulos de Jesus, então o alvo é treinar pessoas que amam umas às outras como Cristo, nosso Senhor, ordenou. Em nossa experiência, as igrejas que têm uma forte cultura de treinamento (como a definimos) acabam construindo comunidades de Cristo profundas, honestas e amorosas. As pessoas destas comunidades não se veem mais como consumidores ou como espectadores, mas como servos que desejam ver o crescimento de outros. Treinamento pode começar pequeno. Pode focalizar-se em indivíduos e no que cada pessoa precisa para crescer, mas o resultado é uma explosão de amor. O que tende a acontecer é que, à medida que as pessoas “abraçam” a visão de ministério e treinamento e começam a expandir-se e desenvolver novos ministérios ao redor de seus dons e circunstâncias específicas, novas pequenas comunhões do povo de Deus se desenvolvem, ou como subgrupos dentro das congregações, ou como novas plantações de igreja. 9. Como os pequenos grupos se encaixam no seu conceito de treinamento? Em muitos lugares hoje, uma rede de pequenos grupos é uma das “treliças” mais importantes da vida da igreja – uma estrutura que permite aos cristãos se reunirem para encorajar uns aos outros com a Bíblia e orar uns pelos outros. No entanto, alguns pastores estão corretamente céticos quanto ao valor dos pequenos grupos. Se esses grupos não são liderados e bem gerenciados, podem se tornar facilmente estruturas ineficazes e até mesmo perigosas nas quais as pessoas se reúnem para compartilhar sua ignorância e nas quais não há supervisão pastoral genuína. Sem treinamento, a delegação do ministério e da autoridade pastoral à estrutura de pequeno grupo é uma abdicação da responsabilidade pastoral. Pequenos grupos podem ser instrumentos eficientes para o ministério, mas somente se treinarmos líderes para que tenham uma profunda compreensão da sã doutrina, um caráter piedoso e a capacidade de entenderem e ensinarem a Bíblia por meio de discussão em grupo. Visto que muitas igrejas não treinam adequadamente seu povo e, portanto, não desenvolvem o tipo de trabalhadores de videira que podem liderar pequenos grupos eficazes, a liderança e o ensino tendem a ser centralizados no(s) pastor(es) ordenado(s) e talvez em poucos líderes principais. Isto protege o evangelho, mas não multiplica o ministério. Pequenos grupos podem ser estruturas bastante úteis nas quais podemos treinar pessoas. Se o líder do grupo vê-se a si mesmo não como um coordenador ou diretor mas como um treinador, isso muda completamente os alvos e a dinâmica do grupo. O alvo do líder do grupo se torna o mesmo alvo de todo o ministério – não apenas fazer discípulos, mas fazer discípulos fazedores de discípulos.

10. Como a sua abordagem de ministério e crescimento se harmoniza com plantar igrejas? A plantação de novas congregações não é uma estratégia fundamental no crescimento do evangelho? Em muitos aspectos, a metáfora de “treliça e videira” nos ajuda a entender e esclarecer o que é tão útil e importante quanto à plantação de igreja. Também nos alerta sobre alguns perigos. Metaforicamente, podemos dizer que, se temos uma treliça com uma videira florescente num lado do jardim e gostaríamos de vê-la crescendo no outro lado do jardim, poderíamos tomar duas atitudes. Poderíamos regar, tratar e cuidar da videira, enquanto ao mesmo tempo manteríamos e expandiríamos a treliça, para que a videira crescesse por toda a cerca de trás e chegasse ao outro lado do jardim. Um megavideira, você diria. Ou poderíamos construir uma nova treliça no outro lado do jardim, tomaríamos uma muda da videira original e começaríamos uma nova videira. Ambas as atitudes são legítimas, e a escolha entre elas depende de vários fatores (inclusive a habilidade da liderança em ser capaz de fazer crescer e manter unida uma grande congregação). Entretanto, quantas igrejas têm descoberto que plantar novas congregações, em novos contextos, lugares e tempos, ou com novas ênfases e estilos têm contribuído realmente para o crescimento da videira. Fazer uma “videira” crescer de 30 ou 40 membros para 120 é frequentemente mais fácil, especialmente em termos das complicações de treliça, do que crescer de 120 para 200. Mas há uma coisa. Construir uma nova treliça e plantar uma nova videira em outro lugar não favorecerá o crescimento, se a videira não for saudável para começar a se expandir. O mero ato de transplantar não produz crescimento evangélico – ou seja, a evangelização, a conversão e o crescimento de discípulos que fazem discípulos de Jesus Cristo. Mas, se esse tipo de crescimento evangélico está acontecendo, e você planta algumas dessas pessoas em outro lugar, as chances são que elas crescerão e se multiplicarão ali, com entusiasmo renovado. Em outras palavras, a empolgação quanto à plantação de igreja pode, às vezes, levar pessoas a pensarem que o mero fato de erguer uma nova treliça em outro lugar resultará numa nova videira saudável e crescente. Mas a coisa principal quanto à plantação de igreja não é a qualidade ou o lugar da treliça, mas a qualidade das pessoas – os trabalhadores de videira – que estão começando a nova obra. Outra vez, a questão retorna a quão bem estamos treinando nosso povo a serem fazedores de discípulos. Para muitos, a atividade de plantar igreja significa erigir uma treliça com características familiares: um prédio, um pastor ordenado, um estatuto e assim por diante. Mas, se entendemos que a obra de videira é a coisa principal, então podemos ser flexíveis quanto ao tipo específico de treliça que precisamos para plantar uma nova videira nesta nova localidade. Por exemplo, podemos começar com um grupo de cristãos que se reúnem numa sala de visitas sem um pastor ordenado. Em qualquer abordagem que seguirmos, o treinamento de trabalhadores de videira é crucial. Precisamos preparar e formar equipes de discípulos engajados no ministério da Palavra guiado pelo Espírito. Precisamos construir ao redor de pessoas e não de estruturas.

11. A sua abordagem do ministério é contrária a igrejas grandes? Você está dizendo que a igreja “ideal” é uma igreja que tem um pastortreinador e 120 membros? É claro que não. Os princípios de ministério que delineamos são, conforme argumentamos, os princípios bíblicos para fazermos discípulos de todas as nações. Eles se aplicam tanto aos pequenos grupos de estudos bíblicos de oito pessoas quanto às megaigrejas de 2.000 membros. Ou seja, o alvo de todo o ministério é que vejamos pessoas se tornando discípulos de Cristo piedosos e maduros, os quais, em imitação de seu Senhor, anseiam por alcançar outros, servi-los e torná-los discípulos. Treinar discípulos em convicção, caráter e competência deve estar no âmago de todo o ministério cristão, independentemente do tamanho da comunhão e de suas estruturas. Por exemplo, sabemos de um pastor que está presentemente lidando com a questão de como fazer sua igreja crescer de 500 para 1.000 pessoas. Ele enfrenta desafios organizacionais e estruturais (desafios de “treliça”); e as habilidades de liderança e de gerenciamento de pessoas que ele precisará são mais importantes do que se estivesse pastoreando uma igreja de 80 membros. Ele sabe que precisa fazer algum “trabalho de gerenciamento” e não apenas “trabalho de execução”. No entanto, este pastor específico também sabe que seu alvo não é conseguir 500 novas pessoas para sentar nos bancos de sua igreja (o que ele poderia conseguir de várias maneiras!), e sim ter 500 novos discípulos de Jesus. Ele também sabe que sozinho não será capaz de achar, reunir e ensinar esses novos discípulos. Isso só acontecerá (pela graça de Deus) se ele continuar treinando seu povo a trabalhar com ele em evangelização, acompanhamento, crescimento e treinamento. Em outras palavras, fazer uma grande congregação crescer não exige apenas liderança talentosa e altamente capaz, mas também um compromisso inabalável com o treinamento de um exército de cooperadores. Exige um compromisso ainda maior com manter as pessoas no centro e não os programas. Devemos reconhecer que nem todos têm capacidades de liderança e personalidade para construir e liderar uma grande congregação. Mas nossa filosofia de ministério nos leva a apoiar, encorajar e ajudar aqueles que fazem isso. O ministério deve ser construído ao redor de pessoas e não de seus dons. Se alguém possui os dons para edificar uma obra evangélica realmente grande e significativa, nós lhe daremos toda assistência e treinamento para fazer isso. Outro ponto importante sobre isto: um de nossos treinadores do Ministry Training Strategy (Estratégia de Treinamento Ministerial) escolheu enviar 30 de seus melhores líderes para o ministério do evangelho ao redor do mundo, resultando em que ele não construiu uma megaigreja. Estes 30 líderes estão agora servindo como pastores, plantadores de igreja, missionários e educadores teológicos. Se os tivesse retido em sua equipe de ministério, quem sabe quão grande seria a sua igreja hoje? Mas, porque ele os deu intencional e generosamente, o evangelho se propagou em muitas frentes. É uma escolha estratégica entre fazermos crescer nossas próprias igrejas e fazermos crescer o evangelho além de nossa obra local. É claro que é possível fazermos ambas as coisas. Mas não devemos valorizar grandes igrejas como a única medida de progresso do evangelho.

12. Eu sou um pastor. Muito do que faço é cuidar daqueles que estão magoados, doentes e necessitados. Com base no que você diz nos capítulos 8 e 9, está sugerindo realmente que não devo mais fazer isso? É claro que não. Os doentes e os que sofrem em nossas congregações precisam de cuidado. O que estou sugerindo é que eles não são os únicos que precisam de seu tempo e ministério. Se você quer realmente cuidar deles e ver real crescimento do evangelho, então a coisa sábia a fazer é treinar e mobilizar os cristãos maduros e piedosos de sua congregação para realizarem algum ministério de cuidar dos outros. Isto pode apresentar algumas escolhas ardilosas para o pastor. Precisamos orar por sabedoria. E haverá crises e necessidades que precisarão da atenção do pastor. Mas, a sua responsabilidade como pastor é “alimentar as ovelhas” – todas elas. Se todo o seu tempo é consumido pelas ovelhas fracas e doentes, as saudáveis não serão alimentadas e podem acabar se desviando para algum outro lugar!

13. Se você está encorajando pessoas a começarem seus próprios ministérios, usando seus dons e oportunidades, toda a coisa não se tornará um pouco confusa e tumultuada? Sim. E o seu problema com isso é...? O fato é que muitos de nós somos “controladores” e colocamos muito valor em que tudo esteja arrumado, organizado e sob controle. Um pouco de tumulto é inevitável no ministério de pessoas. No entanto, o tipo de controle que é necessário é o controle de sã doutrina e de caráter piedoso. Algum caos administrativo e organizacional pode ser gerenciado, mas o caos de pecado e de falsa doutrina causa dano real. Esta é a razão por que é tão importante treinarmos pessoas em convicção, caráter e competência, para que os ministérios em que elas estiverem envolvidas sejam piedosos e alicerçados na Bíblia.$conteudo$
    )
    returning id into v_aula_id;

    insert into public.atividades (aula_id, ordem, pergunta, tipo, razao) values
    (v_aula_id, 1, $p$À pergunta de como começar a treinar quando 'quase não há tempo agora', os autores respondem que treinar é mudança de mentalidade e não tarefa extra: levar alguém junto na visita, conversar sobre o sermão com um cooperador, deixar a pessoa ver você em ação. Que atividade que você já faz sozinho poderia, a partir desta semana, ser feita com alguém ao seu lado sendo treinado no processo?$p$, 'reflexao', null),
    (v_aula_id, 2, $p$Sobre a falta de compromisso dos membros, os autores apontam causas como profissionalismo do ministério, visão clericalizada, gastar tempo com as pessoas erradas e ter as pessoas certas presas em estruturas de 'treliça'. Qual dessas raízes melhor descreve a sua igreja, e há alguém certo que você precisa remover de comissões e atividades para que tenha tempo e energia de ser treinado?$p$, 'reflexao', null),
    (v_aula_id, 3, $p$Quando o pastor pergunta se ministério aberto não vira algo confuso e tumultuado, a resposta dos autores é direta: 'Sim. E o seu problema com isso é...?', distinguindo o caos administrativo gerenciável do caos perigoso de pecado e falsa doutrina. Quanto do seu controle sobre o ministério nasce de zelo pela sã doutrina e quanto nasce do seu desconforto pessoal em soltar as rédeas?$p$, 'reflexao', null);
  end if;

end $migration$;
